import json
def extract_shapes(g):
    from collections import deque
    seen=set(); res={}
    for i,row in enumerate(g):
        for j,v in enumerate(row):
            if v and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); cells=set()
                while q:
                    a,b=q.popleft(); cells.add((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<len(g) and 0<=nb<len(g[0]) and g[na][nb]==v and (na,nb) not in seen:
                            seen.add((na,nb)); q.append((na,nb))
                res.setdefault(v,[]).append(cells)
    return res
def transform(g):
    H,W=len(g),len(g[0])
    sh=extract_shapes(g)
    groups=sorted(sh.items(), key=lambda kv: min(c for s in kv[1] for _,c in s))
    out=[[0]*W for _ in range(H)]
    left=0
    for col,shapes in groups:
        shapes=sorted(shapes, key=len)
        bottom=H
        for s in shapes:
            rs=[r for r,_ in s]; cs=[c for _,c in s]
            h=max(rs)-min(rs)+1; w=max(cs)-min(cs)+1
            top=bottom-h
            for (r,c) in s:
                out[top+(r-min(rs))][left+(c-min(cs))]=col
            bottom=top-1  # one blank row gap
        left+=max(max(c for _,c in s)-min(c for _,c in s)+1 for s in shapes)+1
    return out
